SELECT (SELECT COUNT(*) FROM d1_migrations) AS migrations, (SELECT COUNT(*) FROM d1_migrations WHERE name='0006_account_deletion.sql') AS migration_0006, (SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name GLOB 'life_*') AS app_tables, (SELECT COUNT(*) FROM sqlite_master WHERE name IN ('life_account_deletions','life_deleted_ai_usage','life_ai_usage','life_delete_account')) AS deletion_objects, (SELECT COUNT(*) FROM sqlite_master WHERE type='trigger' AND (name GLOB 'life_*_deleted_insert' OR name GLOB 'life_*_deleted_update')) AS stale_write_guards, (SELECT COUNT(*) FROM life_account_deletions) AS deleted_accounts, (SELECT COUNT(*) FROM life_deleted_ai_usage) AS archived_attempts, (SELECT COUNT(*) FROM sqlite_master WHERE name IN ('life_daily_reminder_intent','life_daily_job_status')) AS scheduler_objects;
